"use client"

import { useGetServices, usePostServices } from "@/src/lib/ReactQuery/query/admin/services/query";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import z from "zod"
import Modal from "../../components/ui/Modal/Modal";
import { useState } from "react";
import { useGetDoctors } from "@/src/lib/ReactQuery/query/admin/doctors/query";
import { TDoctors, TServiceCategory } from "@/src/types";
import { useGetServiceCategory } from "@/src/lib/ReactQuery/query/admin/service-categories/query";

const servicesSchema = z.object({
    title: z.string(),
    description: z.string(),
    content: z.string(),
    price: z.string(),
    priceFrom: z.string(),
    categoryId: z.string(),
    isOms: z.string(),
    duration: z.string(),
    imageUrl: z.string(),
    isActive: z.string(),
    doctorIds: z.array(z.string()),
});
type TservicesSchema = z.infer<typeof servicesSchema>;

export default function ServicesPage() {
    const [isOpenPost,setIsOpenPost] = useState<boolean>(false);
    const servicesPost = usePostServices();
    const doctorsGet = useGetDoctors();
    const categoryGet = useGetServiceCategory();
    const servicesGet = useGetServices();
    const { register, handleSubmit, formState: { errors }, reset } = useForm<TservicesSchema>({
        resolver: zodResolver(servicesSchema),
        defaultValues: {
            title: "",
            description: "",
            content: "",
            price: "",
            priceFrom: "false",
            categoryId: "",
            isOms: "false",
            duration: "",
            imageUrl: "",
            isActive: "true",
            doctorIds: []
        }
    })
    async function onSubmit(data: TservicesSchema) {
        servicesPost.mutate(data);
    }
    return<main>
        <h3>Управление услугами</h3>
        <section>
            <button onClick={() => setIsOpenPost(true)}>Создать</button>
            <table>
                <thead>
                    <tr>
                        <th>Название</th>
                        
                    </tr>
                </thead>
                <tbody>
                    {servicesGet.data && servicesGet.data.length > 0 && servicesGet.data.map((service) => {

                        return<tr key={service.id}>
                            <td>{service.title}</td>
                            <td>{service.description}</td>
                        </tr>
                    })}
                </tbody>
            </table>
        </section>
        <Modal isOpen={isOpenPost} onClose={() => setIsOpenPost(false)}>
            <form onSubmit={handleSubmit(onSubmit)}>
                <label htmlFor="title">Название</label>
                <input type="text" {...register("title")} id="title"/>
                <label htmlFor="description">Описание</label>
                <textarea {...register("description")} id="description"></textarea>
                <label htmlFor="content">content</label>
                <input type="text" {...register("content")} id="content"/>
                <label htmlFor="price">price</label>
                <input type="text" {...register("price")} id="price"/>
                <label htmlFor="priceFrom">priceFrom</label>
                <select {...register("priceFrom")} id="priceFrom">
                    <option value={"true"}>Да</option>
                    <option value={"false"}>Нет</option>
                </select>
                <label htmlFor="categoryId">categoryId</label>
                {categoryGet.data && categoryGet.data.length > 0 && categoryGet.data.map((category: TServiceCategory) => {

                    return <label key={category.id}>
                        <input type="radio" {...register("categoryId")} value={category.id} />
                        {category.title}
                    </label>
                })}
                <label htmlFor="isOms">isOms</label>
                <select {...register("isOms")} id="isOms">
                    <option value={"true"}>Да</option>
                    <option value={"false"}>Нет</option>
                </select>
                <label htmlFor="duration">duration</label>
                <input type="text" {...register("duration")} id="duration"/>
                <label htmlFor="imageUrl">imageUrl</label>
                <input type="text" {...register("imageUrl")} id="imageUrl"/>
                <label htmlFor="isActive">isActive</label>
                <select {...register("isActive")} id="isActive">
                    <option value={"true"}>Да</option>
                    <option value={"false"}>Нет</option>
                </select>   
                {doctorsGet.data && doctorsGet.data.length > 0 && doctorsGet.data?.map((doctor: TDoctors) => {

                    return<label key={doctor.id}>
                        <input type="checkbox" {...register("doctorIds")} value={doctor.id} />
                        {doctor.name}
                    </label>
                })}
                <button type="submit">Создать</button>
            </form>
            <button type="button" onClick={() => setIsOpenPost(false)}>Закрыть</button>
        </Modal>
    </main>
}